<?php require __DIR__ . '/header.php'; if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); db()->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]); } ?><div class="dashboard-title"><div><p class="eyebrow"><?= text('orders') ?></p><h2><?= text('orders') ?></h2></div></div><section class="admin-section"><?php foreach(db()->query('SELECT * FROM orders ORDER BY created_at DESC') as $order): ?><article class="order-card"><div><b>#<?= $order['id'] ?> · <?= e($order['full_name']) ?></b><span><?= e($order['phone']) ?> · <?= e($order['wilaya']) ?> / <?= e($order['commune']) ?></span><span><?= e($order['delivery_method']) ?> · <?= money($order['total']) ?> · <?= e($order['created_at']) ?></span></div><form method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="id" value="<?= $order['id'] ?>"><select name="status" onchange="this.form.submit()"><option>New</option><option <?= $order['status']==='Confirmed'?'selected':'' ?>>Confirmed ✓</option><option <?= $order['status']==='Shipped'?'selected':'' ?>>Shipped</option><option <?= $order['status']==='Cancelled'?'selected':'' ?>>Cancelled</option></select></form></article><?php endforeach; ?></section><?php require __DIR__ . '/footer.php'; ?>
